<script setup lang="ts">
import { computed, nextTick, shallowRef, useTemplateRef, watch } from "vue";
import { literatureStrategiesApi, type StrategyDetail } from "../../api/literatureStrategies";
import StrategyExecutionHistory from "./StrategyExecutionHistory.vue";
import StrategyVersionTimeline from "./StrategyVersionTimeline.vue";
import StrategyActionMenu from "./StrategyActionMenu.vue";
const props = defineProps<{ task: StrategyDetail | null; loading: boolean; rerunning: boolean }>();
const emit = defineEmits<{ action: [action: "rename" | "move" | "clone" | "archive" | "restore", id: number]; rerun: []; close: []; export: [] }>();
const showQuery = shallowRef(false); const comparisonText = shallowRef(""); const comparisonError = shallowRef(""); const comparing = shallowRef(false);
const copyStatus = shallowRef("");
const detailRef = useTemplateRef<HTMLElement>("detail");
const executions = computed(() => props.task?.executions ?? []); const currentResult = computed(() => executions.value[0]?.result_count ?? 0);
function dateLabel(value: string): string { return new Intl.DateTimeFormat("zh-CN", { month: "numeric", day: "numeric", hour: "2-digit", minute: "2-digit", hour12: false }).format(new Date(value)); }
async function compareVersions(): Promise<void> { if (!props.task || props.task.versions.length < 2) return; comparing.value = true; comparisonError.value = ""; try { const sorted = [...props.task.versions].sort((a, b) => b.version - a.version); const result = await literatureStrategiesApi.compareVersions(props.task.id, sorted[1].version, sorted[0].version); comparisonText.value = `v${result.from_version} 与 v${result.to_version} 的真实差异：${JSON.stringify(result.changes)}`; } catch (cause) { comparisonError.value = cause instanceof Error ? cause.message : "无法读取版本差异"; } finally { comparing.value = false; } }
async function copyQuery(): Promise<void> { if (!props.task) return; try { await navigator.clipboard.writeText(props.task.current_version.search_string); copyStatus.value = "检索式已复制"; } catch { copyStatus.value = "复制失败，请手动选择检索式"; } }
watch(() => props.task?.id, async (id) => { if (!id) return; showQuery.value = false; comparisonText.value = ""; copyStatus.value = ""; await nextTick(); detailRef.value?.focus(); });
</script>
<template>
  <aside ref="detail" class="detail" aria-label="检索策略详情" tabindex="-1">
    <p v-if="props.loading" class="detail-loading" aria-live="polite">正在读取策略详情…</p>
    <template v-else-if="props.task">
      <header class="detail-header"><div class="title"><h2>{{ props.task.name }}</h2><p>最后更新：{{ dateLabel(props.task.updated_at) }}</p></div><StrategyActionMenu :strategy-id="props.task.id" :archived="props.task.is_archived" @action="(action, id) => emit('action', action, id)" /><button class="close" type="button" aria-label="关闭策略详情" @click="emit('close')">×</button></header>
      <section class="question"><h3>原始研究问题</h3><p>{{ props.task.current_version.original_query }}</p></section>
      <section class="current-version"><div class="section-row"><h3>当前版本</h3><time>{{ dateLabel(props.task.updated_at) }} 更新</time></div><p><span class="version-tag">v{{ props.task.current_version.version }}</span><span class="framework-tag">{{ props.task.framework }}</span></p><ul><li>▣　{{ props.task.database === 'pubmed' ? 'PubMed' : props.task.database }}</li><li>⌕　{{ props.task.current_version.term_groups.length }} 检索术语</li><li>▣　{{ props.task.current_version.mesh_terms.length }} NLM MeSH</li><li>▣　{{ props.task.current_version.start_year ?? '—' }} – {{ props.task.current_version.end_year ?? '—' }}</li></ul><div class="query-actions"><button type="button" @click="showQuery = !showQuery">{{ showQuery ? '收起检索式' : '查看检索式' }}</button><button v-if="showQuery" type="button" @click="copyQuery">复制</button></div><pre v-if="showQuery" class="query-text">{{ props.task.current_version.search_string }}</pre><p v-if="copyStatus" class="copy-status" aria-live="polite">{{ copyStatus }}</p><p v-if="executions.length" class="result-delta">当前最近执行：<b>{{ currentResult }} 篇结果</b></p></section>
      <StrategyVersionTimeline :versions="props.task.versions" :current-version="props.task.current_version.version" @compare="compareVersions" />
      <p v-if="comparing" class="notice" aria-live="polite">正在比对版本…</p><p v-if="comparisonText" class="notice">{{ comparisonText }}</p><p v-if="comparisonError" class="error" role="alert">{{ comparisonError }}</p>
      <StrategyExecutionHistory :executions="executions" @rerun="emit('rerun')" />
      <footer class="detail-actions"><button type="button" class="primary" :disabled="props.rerunning" @click="emit('rerun')">{{ props.rerunning ? '检索中…' : '再次检索' }}</button><button type="button" @click="emit('action', 'clone', props.task.id)">创建副本</button><button type="button" @click="emit('export')">导出策略</button></footer>
    </template><div v-else class="empty">选择一条策略查看版本与执行记录</div>
  </aside>
</template>
<style scoped>
.detail { display:flex; min-width:0; flex-direction:column; padding:22px 20px 14px; background:var(--surface); overflow:auto; outline:none; }.detail-header { display:flex; gap:8px; align-items:flex-start; padding-bottom:12px; }.pinned,.icon-button,.close { width:25px; height:27px; padding:0; border:0; border-radius:5px; background:transparent; color:var(--text-muted); cursor:pointer; }.pinned { color:#f59e0b; font-size:18px; }.title { min-width:0; flex:1; }.title h2 { margin:0; overflow:hidden; color:var(--text-primary); font-size:16px; white-space:nowrap; text-overflow:ellipsis; }.title span { display:inline-block; margin-top:6px; padding:2px 5px; border-radius:4px; background:#e8f8f1; color:#079669; font-size:10px; font-weight:700; }.title p { margin:7px 0 0; color:var(--text-muted); font-size:10px; }.menu-wrap { position:relative; }.menu { position:absolute; z-index:3; top:30px; right:0; display:grid; width:132px; padding:5px; border:1px solid var(--border-subtle); border-radius:7px; background:var(--surface); box-shadow:0 7px 20px rgb(20 45 90 / 12%); }.menu button { padding:7px; border:0; border-radius:4px; background:transparent; color:var(--text-primary); text-align:left; font:12px inherit; cursor:pointer; }.menu .archive { margin-top:4px; border-top:1px solid var(--border-subtle); color:#ef4444; }.question,.current-version { padding:16px 0; border-bottom:1px solid var(--border-subtle); }.question h3,.current-version h3 { margin:0 0 9px; color:var(--text-primary); font-size:12px; }.question p { margin:0; color:var(--text-secondary); font-size:12px; line-height:1.65; }.section-row { display:flex; justify-content:space-between; }.section-row time { color:var(--text-muted); font-size:10px; }.version-tag,.framework-tag { display:inline-block; margin-right:6px; padding:2px 5px; border-radius:4px; font-size:10px; font-weight:700; }.version-tag { background:#e8f8f1; color:#079669; }.framework-tag { background:#eaf3ff; color:var(--color-primary); }.current-version ul { display:grid; gap:8px; margin:13px 0; padding:0; list-style:none; color:var(--text-secondary); font-size:11px; }.query-text { max-height:120px; margin:14px 0 0; padding:9px; overflow:auto; border-radius:6px; background:var(--surface-muted); color:var(--text-secondary); font:10px/1.5 ui-monospace,Consolas,monospace; white-space:pre-wrap; word-break:break-word; }.result-delta { margin:15px 0 0; color:var(--text-secondary); font-size:11px; }.result-delta b { color:#079669; }.detail-actions { display:grid; grid-template-columns:1.1fr 1fr 1fr; gap:8px; margin-top:auto; padding-top:15px; }.detail-actions button { min-height:33px; padding:0 7px; border:1px solid var(--border-subtle); border-radius:6px; background:var(--surface); color:var(--text-primary); font:700 11px inherit; cursor:pointer; }.detail-actions .primary { border-color:var(--color-primary); background:var(--color-primary); color:#fff; }.detail-actions button:disabled { cursor:wait; opacity:.65; }.detail-loading,.empty { display:grid; min-height:100%; place-items:center; color:var(--text-muted); font-size:12px; }.notice,.error { margin:10px 0 0; padding:7px; border-radius:6px; background:var(--color-primary-soft); color:var(--color-primary); font-size:10px; word-break:break-word; }.error { background:var(--color-danger-soft); color:var(--color-danger); }.query-actions { display:flex; justify-content:flex-end; gap:10px; }.query-actions button { padding:0; border:0; background:transparent; color:var(--color-primary); font:700 11px inherit; cursor:pointer; }.copy-status { margin:6px 0 0; color:var(--color-primary); font-size:10px; }
</style>
